ROOT=Path(__file__).resolve().parents[1]
OUT=ROOT/'dist'
BASE=''
SEED=ROOT/'content/assets'
M=reader.M
F=json.loads((SEED/'framework.json').read_text())
DATA=json.loads((ROOT/'content/chart-data.js').read_text().split('=',1)[1].strip().rstrip(';'))
E=lambda s:html.escape(str(s),quote=True)
NAV=[('overview','报告概览','Overview',''),('report','报告全文','Report','report'),('data','指标与数据','Indicators & data','data/'),('presentation','互动演示','Interactive','presentation/'),('film','宣传影片','Film','film/'),('release','发布中心','Release centre','release/')]
SEARCH=[]
def tr(lang,z,e):return z if lang=='zh' else e
def home(lang):return '/' if lang=='zh' else '/en/'
def path(lang,route):return '/2026/'+lang+'/'+route

def navurl(lang,key):
    route=next(n[3] for n in NAV if n[0]==key)
    return home(lang) if not route else path(lang,'' if route=='report' else route)
def a(url,label,cls='inline-link',extra=''):return f'<a href="{E(url)}" class="{cls}" {extra}>{label}</a>'
def p(text,cls=''):return f'<p class="{cls}">{E(text)}</p>'
def note(lang):return '<div class="reader-note">'+tr(lang,'2026 在线版 · 前置内容与第一章已完成网页和 PDF 对齐；第四章 4.2—4.6 暂为全景与研究框架。各图按标注范围阅读。','2026 online edition · The opening pages and Chapter 1 are aligned with the PDF. Sections 4.2–4.6 currently provide landscapes and research frameworks. Read each figure within its labelled scope.')+'</div>'
def section(sid,title,body):return f'<section id="{sid}" class="content-block"><h2>{title}</h2>{body}</section>'
def chain(lang):
    items=[('GOSD',tr(lang,'报告品牌 · 全球开源发展报告','Report · Global Open Source Development Report'),tr(lang,'承载年度研究、证据与行动建议，是整套报告的统一标识。','The common identity for the annual research, evidence and recommended actions.')),('OSDG',tr(lang,'发展目标 · 连接 UN SDGs','Development goals · Linked to UN SDGs'),tr(lang,'以开源发展目标（OSDGs）连接开源发展与可持续发展议题。','Open Source Development Goals (OSDGs) connect open source development with sustainability.')),('OSDI',tr(lang,'量化评估 · 指标体系','Quantitative assessment · Indicators'),tr(lang,'将发展目标转化为可观测、可解释、可追踪的指标。','Translate the goals into observable, interpretable and traceable measures.'))]
    return '<div class="identity-chain" aria-label="GOSD → OSDG → OSDI">'+''.join(f'<div class="identity-item"><b>{x[0]}{(" <span aria-hidden=\"true\">→</span>" if i<2 else "")}</b><small>{x[1]}</small>{p(x[2])}</div>' for i,x in enumerate(items))+'</div>'

def wheel(lang):
    def point(r,angle):return (170+r*math.sin(math.radians(angle)),170-r*math.cos(math.radians(angle)))
    def arc(r1,r2,s,e):
        x,y=point(r2,s);x2,y2=point(r2,e);x3,y3=point(r1,e);x4,y4=point(r1,s)
        return f'M{x:.2f},{y:.2f} A{r2},{r2} 0 0,1 {x2:.2f},{y2:.2f} L{x3:.2f},{y3:.2f} A{r1},{r1} 0 0,0 {x4:.2f},{y4:.2f} Z'
    out=['<svg viewBox="0 0 340 340" role="group" aria-label="'+tr(lang,'OSDG 四支柱、十维度，可选择探索','OSDG: explore four pillars and ten dimensions')+'">']
    for i,pillar in enumerate(F['P']):
        dims=[d for d in F['D'] if d[4]==i]
        start=i*90
        out.append(f'<a href="{path(lang,"data/goals/")}#pillar-{i+1}" aria-label="{E(pillar[1 if lang=="zh" else 2])}"><title>{E(pillar[1 if lang=="zh" else 2])}</title><path d="{arc(66,106,start+2,start+88)}" fill="var(--p{i+1})"/><text x="{point(85,start+45)[0]:.1f}" y="{point(85,start+45)[1]+4:.1f}" text-anchor="middle" font-size="13" fill="#082a42">X{i+1}</text></a>')
        for j,d in enumerate(dims):
            s=start+j*90/len(dims)+1;e=start+(j+1)*90/len(dims)-1;x,y=point(129,(s+e)/2)
            out.append(f'<a href="{path(lang,"data/goals/")}#dimension-{d[0].replace(".","-")}" aria-label="{E(d[1 if lang=="zh" else 2])}"><title>{E(d[1 if lang=="zh" else 2])}</title><path d="{arc(112,149,s,e)}" fill="var(--p{i+1})" opacity=".65"/><text x="{x:.1f}" y="{y+4:.1f}" text-anchor="middle" font-size="12" fill="#082a42">{d[0]}</text></a>')
    out.append('<text x="170" y="172" class="wheel-center" font-size="28" font-weight="600">OSDG</text><text x="170" y="191" class="wheel-center" font-size="8" letter-spacing="2">GOALS</text></svg>')
    return ''.join(out)

def header(lang,active,route,is_home=False):
    t=lambda z,e:tr(lang,z,e);other='en' if lang=='zh' else 'zh'
    counterpart=home(other) if is_home else path(other,route)
    logo_lang='cn' if lang=='zh' else 'en'
    partners=(f'<div class="header-partners" aria-label="CCOSI · X-lab AI"><span class="partner-ccosi"><img class="partner-light" src="/assets/ccosi-{logo_lang}-blue.svg" alt="CCOSI" width="110" height="44"><img class="partner-dark" src="/assets/ccosi-{logo_lang}-white.svg" alt="CCOSI" width="110" height="44"></span><span class="partner-divider" aria-hidden="true"></span><span class="partner-xlab"><img class="partner-light" src="/assets/xlab-ai-light.png" alt="X-lab AI" width="106" height="46"><img class="partner-dark" src="/assets/xlab-ai-dark.png" alt="X-lab AI" width="106" height="46"></span></div>') if is_home else ''
    links=''.join(a(navurl(lang,n[0]),n[1 if lang=='zh' else 2],'','aria-current="page"' if n[0]==active else '') for n in NAV)
    return f'''<a class="skip" href="#main">{t('跳至正文','Skip to content')}</a><header class="site-header"><div class="header-inner"><a class="gosd-brand" href="{home(lang)}" aria-label="{t('GOSD 全球开源发展报告首页','GOSD report home')}"><span class="gosd-wordmark">GOSD</span><span class="brand-caption">{t('全球开源发展报告','GLOBAL OPEN SOURCE')}<small>{t('GLOBAL OPEN SOURCE DEVELOPMENT','DEVELOPMENT REPORT')}</small></span><span class="brand-year">2026</span></a>{partners}<nav id="site-nav" aria-label="{t('主要导航','Main navigation')}">{links}</nav><div class="header-tools"><button id="search-open" type="button" aria-label="{t('搜索报告','Search the report')}" title="{t('搜索报告','Search the report')}"><svg viewBox="0 0 24 24" aria-hidden="true"><circle cx="10" cy="10" r="6.5"/><path d="m15 15 6 6"/></svg></button><a id="language-link" href="{counterpart}" lang="{other}">{t('EN','中文')}</a><button id="theme-toggle" type="button" aria-pressed="false">{t('深色','Dark')}</button><button id="nav-toggle" class="nav-toggle" type="button" aria-expanded="false" aria-controls="site-nav">{t('菜单','Menu')}</button></div></div></header>'''
def footer(lang):
    t=lambda z,e:tr(lang,z,e)
    return f'''<footer class="shell site-footer"><div class="footer-brand"><strong>GOSD</strong><div>{t('2026 全球开源发展报告','Global Open Source Development Report 2026')}<small>{t('2026 在线版 · 持续更新','2026 ONLINE EDITION · CONTINUOUSLY UPDATED')}</small></div></div><div class="footer-links">{a(path(lang,'release/'),'发布资料' if lang=='zh' else 'Release materials','')}{a(path(lang,'methodology/'),t('方法与范围','Methods & scope'),'')}{a(path(lang,'release/versions/'),t('版本记录','Version history'),'')}{a('#top',t('回到顶部 ↑','Back to top ↑'),'')}</div></footer><dialog id="site-search" class="site-search" aria-labelledby="search-title"><div class="search-dialog-head"><h2 id="search-title">{t('搜索报告','Search the report')}</h2><button id="search-close" aria-label="{t('关闭搜索','Close search')}">×</button></div><div class="search-body"><label for="search-input">{t('查找章节、研究问题与指标','Find chapters, research questions and indicators')}</label><input id="search-input" type="search" placeholder="{t('例如：模型、公共价值、DevScale','e.g. models, public value, DevScale')}" autocomplete="off"><div id="search-results" class="search-results" aria-live="polite"></div></div></dialog>'''

def sidebar(lang,active,route,unit=None):
    t=lambda z,e:tr(lang,z,e);rows=[]
    if active=='report':
        rows=[('',t('全书目录','Contents'))]+[(u['route'],(u.get('number','')+' '+u['title'][lang]).strip()) for u in reader.UNITS]
    elif active=='data':rows=[('data/',t('指标与数据概览','Overview')),('data/goals/',t('OSDG 目标框架','OSDG goals')),('data/indicators/',t('OSDI 指标词典','OSDI indicators')),('data/explore/',t('图表与数据探索','Charts and data')),('data/sources/',t('数据文件与来源','Data files and sources')),('methodology/',t('附录 A · 方法与范围','Appendix A · Methods'))]
    elif active=='release':rows=[('release/',t('发布中心','Release centre')),('downloads/',t('资料下载与引用','Downloads and citation')),('release/news/',t('动态与解读','Updates and insights')),('release/versions/',t('版本与更新','Versions and updates'))]
    elif active=='presentation':rows=[('presentation/',t('报告互动演示','Report review presentation')),('presentation/#demo',t('进入演示','Open the presentation'))]
    elif active=='film':rows=[('film/',t('影片概览','Film overview')),('film/#film-status',t('制作进度','Production status')),('film/#related',t('相关内容','Related material'))]
    out=['<div class="nav-label">'+t('栏目目录','IN THIS SECTION')+'</div>']
    for r,label in rows:
        out.append(a(path(lang,r),E(label),'','aria-current="page"' if r==route else 'aria-current="location"' if r=='release/news/' and route.startswith(r) else ''))
        if r==route and route=='data/goals/':
            out.extend(a('#dimension-'+d[0].replace('.','-'),E(d[0]+' '+d[1 if lang=='zh' else 2]),'local-section') for d in F['D'])
        if unit and r==route:
            out.extend(a('#'+s['id'],E(s['number']+' '+s['title'][lang]),'local-section') for s in unit.get('sections',[]))
        if r==route and route=='methodology/':
            out.extend(a('#'+hid,E(title),'local-section') for hid,title,level in report.headings(report.METHOD,'method') if level==2)
    if unit and unit.get('id')=='ch03':out.append(a('#gosr-review',t('评审与方法缺口','Review and method gaps'),'review-section-link'))
    if route=='chapters/01/':out=[reading_experience.sidebar(lang,report)]
    if route=='summary/':out=['<div class="nav-label">'+t('摘要导览','IN THIS SUMMARY')+'</div>']+[a('#summary-'+str(i),label,'local-section') for i,label in enumerate([t('年度主张','The central idea'),t('关键观察','Key observations'),t('共同行动','Shared action'),t('继续阅读','Continue reading')],1)]
    if route=='introduction/':out=['<div class="nav-label">'+t('引言导览','IN THIS INTRODUCTION')+'</div>',a('#declaration-overview',t('宣言全景','Declaration overview'),'local-section')]+[a('#introduction-'+str(i),label,'local-section') for i,label in enumerate([t('时代呼唤','The call of our time'),t('共同愿景','Our shared vision'),t('核心原则','Core principles'),t('行动共识','A consensus for action'),t('宣言结语','Declaration closing'),t('从愿景到行动','From vision to action')],1)]
    if active=='report' and route in ['', 'summary/', 'introduction/']:
        entry='<div class="front-entry-links"><div class="nav-label">'+t('阅读起点','START READING')+'</div>'
        for r,label in [('',t('全书目录','Contents')),('summary/',t('执行摘要','Executive summary')),('introduction/',t('引言','Introduction'))]:
            entry+=a(path(lang,r),label,'','aria-current="page"' if r==route else '')
        entry+='</div>'
        if route=='':
            out=['<div class="nav-label">'+t('六章正文','SIX CHAPTERS')+'</div>']
            for c in M['chapters']:
                label=t('第'+c['number']+'章','Chapter '+c['number'])+' · '+c['title'][lang].split('（')[0].split(' (')[0]
                out.append(a('#contents-chapter-'+c['number'],E(label),'local-section'))
            out.append(a('#contents-appendices',t('附录与方法','Appendices & methods'),'local-section'))
        out.insert(0,entry)
    return '<aside class="sidebar-wrap"><button class="side-toggle" type="button" aria-expanded="false" aria-controls="section-nav">'+t('栏目目录','Section contents')+' <span>＋</span></button><nav class="book-nav" id="section-nav" aria-label="'+t('栏目目录','Section contents')+'">'+''.join(out)+'</nav></aside>'

def emit(lang,route,active,title,deck,content,unit=None,scripts='',is_home=False):
    t=lambda z,e:tr(lang,z,e)
    if route=='chapters/01/':title=t('第一章 · ','Chapter 1 · ')+title
    address=home(lang) if is_home else path(lang,route)
    SEARCH.append({'lang':lang,'title':title,'description':deck,'url':address,'category':next(n[1 if lang=='zh' else 2] for n in NAV if n[0]==active)})
    if is_home:main='<main id="main" class="portal-main shell">'+content+'</main>'
    else:
        category=next(n[1 if lang=='zh' else 2] for n in NAV if n[0]==active)
        crumbs=a(home(lang),t('首页','Home'),'')+'<span class="sep">/</span>'
        if navurl(lang,active)!=address:crumbs+=a(navurl(lang,active),category,'')+'<span class="sep">/</span>'
        crumbs+='<span aria-current="page">'+E(title)+'</span>'
        pnav=''
        if unit and route not in ['summary/', 'introduction/']:
            at=reader.UNITS.index(unit);previous=reader.UNITS[at-1] if at else None;following=reader.UNITS[at+1] if at<len(reader.UNITS)-1 else None
            pnav='<nav class="reader-page-nav" aria-label="'+t('前后篇章','Adjacent pages')+'">'+(a(path(lang,previous['route']),'← '+E(previous['title'][lang]),'') if previous else a(path(lang,''),t('← 全书目录','← Contents'),''))+(a(path(lang,following['route']),E(following['title'][lang])+' →','') if following else a(path(lang,'release/'),t('发布中心 →','Release centre →'),''))+'</nav>'
        main=f'<div class="shell"><nav class="breadcrumbs" aria-label="{t("当前位置","Breadcrumb")}">{crumbs}</nav><a class="return-source" id="return-source" hidden></a></div><div class="shell reader-head"><span class="eyebrow">GOSD / 2026 · {E(category)}</span><h1>{E(title)}</h1><p class="deck">{E(deck)}</p><div class="reader-meta"><span>{t("评审预览 · 2026.10.16","Review preview · 2026.10.16")}</span><span>2025.07 — 2026.06</span></div></div><div class="shell reader-layout">{sidebar(lang,active,route,unit)}<main id="main" class="reader-main" data-page-title="{E(title)}">{content}{pnav}</main></div>'
    if route=='chapters/02/':scripts+='<link rel="stylesheet" href="/vmap.css"><script src="/vmap.js" defer></script><link rel="stylesheet" href="/cmap.css?v=20261020-cmap-concise"><script src="/cmap.js?v=20261020-cmap-concise" defer></script><script type="module" src="/cmap-globe.js?v=20261020-cmap-concise"></script>'
    amap_assets='<link rel="stylesheet" href="/amap.css?v=20261020-v4"><script src="/assets/amap/d3.min.js" defer></script><script src="/assets/amap/publication-data.js?v=20261020-v4" defer></script><script src="/amap.js?v=20261020-v4" defer></script><link rel="stylesheet" href="/dmap.css?v=20261020-sources-layout"><script src="/assets/dmap/data.js" defer></script><script src="/dmap.js?v=20261020-sources-layout" defer></script>' if route=='chapters/02/' else ''
    gmap_assets='<link rel="stylesheet" href="/gmap.css?v=20261020-pub3"><script src="/assets/gmap/publication-data.js?v=20261020-pub3" defer></script><script src="/gmap.js?v=20261020-pub3" defer></script>' if route=='chapters/02/' else ''
    gosm_assets='<link rel="stylesheet" href="/gosm.css?v=gosm-openness-v2-atlas"><link rel="stylesheet" href="/gosm-supply.css?v=gosm-supply-v9-story"><script src="/gosm-supply.js?v=gosm-supply-v9-story" defer></script><script src="/assets/amap/d3.min.js" defer></script><link rel="stylesheet" href="/gosm-influence.css?v=gosm-influence-v3-story"><script src="/gosm-influence.js?v=gosm-influence-v3-story" defer></script><link rel="stylesheet" href="/gosm-openness.css?v=gosm-openness-v2-atlas"><script src="/gosm-openness.js?v=gosm-openness-v2-atlas" defer></script><script src="/gosm.js?v=gosm-openness-v2-atlas" defer></script>' if route=='chapters/05/' else ''
    if route=='chapters/02/':
        main=main.replace(t('评审预览 · 2026.10.16','Review preview · 2026.10.16'),t('在线版','Online edition')).replace('<span>2025.07 — 2026.06</span>','')
    if route=='chapters/05/':
        main=main.replace('2025.07 — 2026.06',t('各图按来源标注统计期与快照','Dates and scope are specified in each figure')).replace('2026.10.16','2026.10.17')
    reading_assets='<link rel="stylesheet" href="/goso-reading.css?v=20261021-layout"><script src="/goso-reading.js?v=20261021-layout" defer></script>' if route=='chapters/02/' else ''
    if route=='chapters/03/':reading_assets+='<link rel="stylesheet" href="/company-ranking.css"><script src="/company-ranking.js" defer></script><link rel="stylesheet" href="/rankings.css"><script src="/ranking-details.js" defer></script><script src="/rankings.js" defer></script>'
    reading_page='chapter1' if route=='chapters/01/' else 'introduction' if route=='introduction/' else 'summary' if route=='summary/' else 'overview' if is_home else 'contents' if route=='' else ''
    front_assets='<link rel="stylesheet" href="/reading-experience.css"><script src="/reading-experience.js?v=20261019-ch1-captions" defer></script>'
    if route=='presentation/':front_assets+='<link rel="stylesheet" href="/review-deck.css"><link rel="stylesheet" href="/concept-lenses.css"><script src="/concept-lenses.js" defer></script><script src="/review-deck.js" defer></script>'
    chapter1_assets='<link rel="stylesheet" href="/chapter1-restored.css?v=20261019-ch1-complete"><link rel="stylesheet" href="/chapter1-release.css?v=20261018-release"><script src="/chapter1-restored.js?v=20261019-ch1-story" defer></script><script src="/chapter1-theme-map.js?v=20261018-release" defer></script>' if route=='chapters/01/' else ''
    if route=='chapters/01/':
        main=main.replace('评审预览 · 2026.10.16','正式发布 · 更新 2026.10.19').replace('Review preview · 2026.10.16','Published · Updated 2026.10.19').replace('2025.07 — 2026.06',t('各图标注统计期','Periods are labelled per figure'))
    action_assets='<link rel="stylesheet" href="/chapter6.css?v=20261018-review"><script src="/chapter6.js?v=20261018-review" defer></script>' if route=='chapters/06/' else ''
    if route=='chapters/06/':
        main=main.replace('评审预览 · 2026.10.16','第六章评审版 · 2026.10.18').replace('Review preview · 2026.10.16','Chapter 6 review · 2026.10.18').replace('2025.07 — 2026.06',t('综合前文证据 · 行动建议','Evidence synthesis · Recommended actions'))
    architecture_assets='<link rel="stylesheet" href="/report-architecture.css?v=20261018-journey"><script src="/report-architecture.js?v=20261018-journey" defer></script>' if 'id="fig-report-logic"' in content else ''
    if is_home or route in ['', 'summary/', 'introduction/']:
        architecture_assets+='<link rel="stylesheet" href="/frontmatter.css?v=20261019-front-baseline">'
        main=main.replace('评审预览 · 2026.10.16','在线版 · 更新 2026.10.19').replace('Review preview · 2026.10.16','Online edition · Updated 2026.10.19')
        if route=='' and not is_home:main=main.replace('2025.07 — 2026.06',t('六章 · 三十个小节','Six chapters · Thirty sections'))
    if route in ['release/', 'downloads/']:
        architecture_assets+='<link rel="stylesheet" href="/frontmatter.css?v=20261019-front-baseline">'
    if is_home: architecture_assets+='<link rel="stylesheet" href="/overview.css?v=20261018-title-hierarchy"><link rel="stylesheet" href="/cocreation.css?v=20261018-final"><script src="/cocreation.js?v=20261018-final" defer></script><script src="/cocreation-cosmos.js?v=20261018-final" defer></script>'
    if route=='summary/':
        architecture_assets+='<link rel="stylesheet" href="/executive-summary.css?v=20261019-policy-summary">'
        main=main.replace('2025.07 — 2026.06',t('主统计期 2025.07—2026.06 · 其余按图标注','Main period: July 2025–June 2026 · Other dates labelled per figure'))
    if route=='introduction/':
        architecture_assets+='<link rel="stylesheet" href="/declaration-introduction.css?v=20261019-front-baseline"><link rel="stylesheet" href="/declaration-flow.css?v=20261019-clean"><script src="/declaration-flow.js?v=20261019-centered" defer></script>'
        main=main.replace('2025.07 — 2026.06',t('价值起点 · 七项原则','A value foundation · Seven principles'))
    if route=='appendices/declaration/':
        main=main.replace('评审预览 · 2026.10.16','在线版 · 更新 2026.10.19').replace('Review preview · 2026.10.16','Online edition · Updated 2026.10.19').replace('2025.07 — 2026.06',t('宣言全文收录于引言','Full declaration in the introduction'))
